import AppKit

func creativeFillSelfTest(){
    let viewport=Tracker(frame:NSRect(x:0,y:0,width:1440,height:900));viewport.playing=true;viewport.row=0
    for i in 0..<128{viewport.followVisibleRow(length:128,playhead:i);precondition(viewport.scroll<=i&&i<viewport.scroll+viewport.rowsVisible)}
    precondition(viewport.scroll==128-viewport.rowsVisible);viewport.followVisibleRow(length:128,playhead:0);precondition(viewport.scroll==0)
    viewport.row=90;viewport.followVisibleRow(length:128,playhead:4);precondition(viewport.scroll==0);viewport.playing=false;viewport.followVisibleRow(length:128,playhead:-1);precondition(viewport.scroll<=90&&90<viewport.scroll+viewport.rowsVisible)
    viewport.playing=true;viewport.followVisibleRow(length:16,playhead:15);precondition(viewport.scroll==0)
    func generated(_ role:FillRole,_ preset:Int,_ seed:UInt64,_ settings:FillSettings,count:Int=64,context:[Int:FillHarmony]=[:])->[Cell]{var g=CreativeFill(role:role,preset:preset,options:settings,instrument:role.factory,start:0,count:count,context:context,rng:FillRNG(state:seed));return g.generate()}
    var base=FillSettings();base.drumNote=60
    var wet=base;wet.fxAmount=100;var dry=base;dry.fxAmount=0;var kinds=Set<Int>();for role in FillRole.allCases{for seed in 0..<12{let p=generated(role,role.presets.count-1,UInt64(seed),wet),q=generated(role,role.presets.count-1,UInt64(seed),dry);for (a,b) in zip(p,q){precondition(a.notes==b.notes&&a.velocity==b.velocity&&a.micro==b.micro);if b.fx==1||b.fx==2{precondition(a.fx==b.fx&&a.fxValue==b.fxValue)};for fx in [a.fx ?? 0,a.fx2 ?? 0] where fx>=4{precondition([4,5,6,8].contains(fx));kinds.insert(fx);if fx==8{precondition(validEQ(a.fx==8 ? a.eq1 ?? []:a.eq2 ?? []))}};precondition(![4,5,6,8].contains(b.fx ?? 0) && ![4,5,6,8].contains(b.fx2 ?? 0))}}};precondition(kinds==Set([4,5,6,8]))
    var eqVariants=Set<[Int]>();for seed in 0..<16{for c in generated(.lead,FillRole.lead.presets.count-1,UInt64(seed),wet){if let eq=c.eq1{eqVariants.insert(eq)};if let eq=c.eq2{eqVariants.insert(eq)}}};precondition(eqVariants.count>20)
    let four=generated(.kick,0,11,base),eight=generated(.kick,1,12,base),snare=generated(.snare,0,13,base)
    precondition(four.indices.filter{!four[$0].notes.isEmpty}==Array(stride(from:0,to:64,by:4)))
    precondition(eight.indices.filter{!eight[$0].notes.isEmpty}==Array(stride(from:0,to:64,by:8)))
    precondition(snare.indices.filter{!snare[$0].notes.isEmpty}==[4,12,20,28,36,44,52,60])
    for i in 4...6 {let h=generated(.hat,i,9,base);let roll=[10,20,30][i-4];precondition(h[15].fx==2&&h[15].fxValue==roll)}
    for role in FillRole.allCases{var unique=[[Cell]]();for seed in 0..<32{let p=generated(role,role.presets.count-1,UInt64(seed),base);precondition(!unique.contains(p));unique.append(p)};for preset in role.presets.indices{for scale in (role.melodic ? Array(fillScales.indices):[1]){var settings=base;settings.root=11;settings.scale=scale;settings.octave=role.octave;let p=generated(role,preset,UInt64(325+preset+scale),settings);let active=p.filter{!$0.notes.isEmpty};precondition(!active.isEmpty);for c in active{precondition(c.instrument==role.factory&&c.notes.count<=8&&c.notes.allSatisfy{(0...127).contains($0)}&&(1...100).contains(c.velocity ?? 0)&&(1...100).contains(c.volume ?? 0)&&(-50...50).contains(c.pan ?? 999)&&(0...75).contains(c.micro ?? 999));if role.melodic{precondition(c.notes.allSatisfy{fillScales[scale].notes.contains(($0-settings.root+120)%12)})};if role == .chords{precondition(c.notes.count>=3 && !c.label.isEmpty&&c.harmonicRoot != nil)}};if role == .hat{for b in stride(from:0,to:64,by:16){let values=p[b..<b+16].compactMap{$0.velocity};precondition(Set(values).count==values.count)}}}}}
    let chord=generated(.chords,7,19,base);var context=[Int:FillHarmony](),current:FillHarmony?;for i in chord.indices{if let r=chord[i].harmonicRoot{current=FillHarmony(root:r,notes:chord[i].notes)};if let current{context[i]=current}};let bass=generated(.bass,0,8,base,context:context);for i in bass.indices where !bass[i].notes.isEmpty{precondition(bass[i].notes[0]%12==context[i]!.root%12)}
    let t=Tracker(frame:NSRect(x:0,y:0,width:1440,height:900));t.rec=true;t.fillRole = .hat
    func key(_ code:UInt16,_ chars:String=""){let e=NSEvent.keyEvent(with:.keyDown,location:.zero,modifierFlags:[],timestamp:0,windowNumber:0,context:nil,characters:chars,charactersIgnoringModifiers:chars,isARepeat:false,keyCode:code)!;t.keyDown(with:e);t.held.remove(code)}
    key(118);precondition(t.modal==5);key(98);let a=t.fillPreview!.pattern.cells[0];precondition(t.pattern.cells[0].allSatisfy{$0.notes.isEmpty});key(98);let b=t.fillPreview!.pattern.cells[0];precondition(a != b);key(53);precondition(t.modal==0&&t.pattern.cells[0].allSatisfy{$0.notes.isEmpty});t.fill();t.generateFill(random:true);t.applyFill();precondition(t.trackDefaults[0]==1&&t.pattern.cells[0].contains{!$0.notes.isEmpty});t.history(true);precondition(t.trackDefaults[0] == -1&&t.pattern.cells[0].allSatisfy{$0.notes.isEmpty});t.track=1;t.row=7;t.anchor=(1,4);t.fillRole = .kick;t.fill();t.generateFill(random:false);t.applyFill();precondition(t.pattern.cells[1][4].notes.count==1&&t.pattern.cells[1][0].notes.isEmpty&&t.pattern.cells[1][8].notes.isEmpty)
    print("Creative Fill: all presets/scales, 192 random variants, unique hat velocities, chord/bass harmony, preview/cancel/apply/undo and range passed")
}
